test("[BEVESTIG-DICHT] every RPC a screen calls with the session client is granted to authenticated", () => {
  // The revoke list and the call sites must never disagree again: a function in the revoke list
  // may not be called with the session client anywhere, and confirm_bank_payment — which is —
  // must not be in it. Its regrant migration exists and is the later word.
  const revoke = readFileSync("supabase/migrations/rpc_anon_revoke.sql", "utf8");
  // The SECOND list — the one that revokes from `authenticated`. The first revokes from `anon`
  // and rightly names every function.
  const authPart = revoke.slice(revoke.indexOf("Deze staan in geen enkele call site met de sessieclient"));
  const listed = [...authPart.matchAll(/^\s*'([a-z_]+)',?\s*$/gm)].map((m) => m[1]);
  assert.ok(listed.includes("seed_invoice_counter"), "the revoke list is where it was");
  assert.ok(!listed.includes("confirm_bank_payment"), "confirm_bank_payment is called by /api/bank/confirm with the session client");
  const regrant = readFileSync("supabase/migrations/confirm_bank_payment_regrant.sql", "utf8");
  assert.match(regrant, /GRANT EXECUTE ON FUNCTION %s TO authenticated/);
  assert.match(code("src/app/api/bank/confirm/route.ts"), /const atomicFn = withAmount \? "allocate_bank_payment" : "confirm_bank_payment";/);
});

test("[ANON-RPC] the server-only RPCs really are server-only", () => {
  // De tweede lijst in de migratie trekt óók `authenticated` in. Dat mag alleen als geen enkel
  // scherm ze via de sessieclient aanroept — anders zet deze migratie een knop stil. Deze poort
  // is de reden dat de lijst later niet stilletjes fout kan worden: voegt iemand een aanroep met
  // de sessieclient toe, dan faalt hij hier en niet bij een gebruiker.
  // [BEVESTIG-DICHT] confirm_bank_payment left this list: /api/bank/confirm calls it with the
  // session client (bank_confirm_atomic), and its grant is restored (confirm_bank_payment_regrant).
  const SERVER_ONLY = [
    "seed_invoice_counter", "recompute_invoice_amount_paid",
    "fair_use_consume", "fair_use_release",
  ];
  const walk = (dir: string): string[] => {
    const out: string[] = [];
    for (const e of readdirSync(dir)) {
      const p = `${dir}/${e}`;
      if (statSync(p).isDirectory()) out.push(...walk(p));
      else if (/\.tsx?$/.test(p) && !p.endsWith(".test.ts")) out.push(p);
    }
    return out;
  };
  const bronnen = walk("src");
  for (const fn of SERVER_ONLY) {
    for (const file of bronnen) {
      const src = readFileSync(file, "utf8");
      // The NAME, not only `rpc("name"`: the confirm route reached a revoked function through a
      // variable (`const atomicFn = … ? "…" : "confirm_bank_payment"`) and this gate, matching the
      // literal call only, waved it through — every plain Bevestig on /bank then answered 500.
      for (const regel of code(file).split("\n")) {
        if (!regel.includes(`"${fn}"`) && !regel.includes(`'${fn}'`)) continue;
        assert.match(regel, /(pipeline|insertPipeline|pipelineForConfirm)\s*(as any\s*)?\)?\.rpc/,
          `${fn} is revoked from 'authenticated' — it may only be called with the service-role client, and only by its literal name in the rpc call (${file})`);
      }
    }
  }
});

// ─── [ZOEKPAD] Een vast zoekpad op de negen eigen functies ────────────────────
//
// Hygiëne, geen gat, en dat verschil staat er met opzet bij: een migratie die zich voordoet als
// noodreparatie maakt de volgende noodreparatie ongeloofwaardig. Op de productiedatabase gemeten
// staat geen van de negen op SECURITY DEFINER, en heeft anon noch authenticated CREATE op enig
// schema — twee onafhankelijke redenen waarom er vandaag niets te kapen valt.
//
// Het wordt toch vastgezet omdat die twee redenen OMSTANDIGHEDEN zijn, geen afspraken. Wie morgen
// één van deze bewakers SECURITY DEFINER maakt — een volstrekt normale wijziging — erft anders
// stilzwijgend een echte kwetsbaarheid, en niets zou daarop wijzen.

test("[ZOEKPAD] every own function is pinned, and pg_temp comes last", () => {
  const sql = readFileSync("supabase/migrations/function_search_path.sql", "utf8");
  for (const fn of [
    // De vier bewakers eerst — die hebben het meest te verliezen.
    "prevent_billing_self_grant", "prevent_accountant_amount_changes",
    "prevent_verwerkt_invoice_changes", "guard_paid_when_verwerkt",
    "invoices_search_vector_update", "documents_search_vector_update",
    "set_updated_at", "touch_updated_at", "get_accountant_for_zzper",
  ]) {
    assert.ok(sql.includes(`'${fn}'`), `${fn} must get a pinned search_path`);
  }
  // pg_temp ACHTERAAN. Laat je het weg, dan zet Postgres het impliciet vooraan, en dan is het
  // tijdelijke schema van de aanroeper juist wél weer een plek om een naam te kapen — precies wat
  // deze migratie afsluit. Een half toegepast idee is hier erger dan geen idee.
  assert.match(sql, /SET search_path = public, pg_catalog, pg_temp/,
    "pg_temp must be named explicitly and LAST, or the fix reopens what it closes");
  assert.ok(!/search_path = pg_temp/.test(sql), "pg_temp must never come first");
  // `public` moet erin, want get_accountant_for_zzper noemt accountant_clients zonder schema.
  assert.match(sql, /accountant_clients/,
    "the one unqualified table reference is why the path cannot be empty — say so");
  // En de migratie moet zeggen dat dit GEEN gat was. Zie de kop hierboven.
  assert.match(sql, /HYGIËNE, geen gat/,
    "a migration that poses as an emergency spends credibility the next emergency needs");
});

test("[FACTUUR-BIJLAGE] a copied invoice does not inherit the attachment", () => {
  // Twee routes maken een nieuwe factuur uit een bestaande. Zou de bijlage meereizen, dan krijgt de
  // klant bij élke maandelijkse factuur de werkbon van de eerste maand, en bij elk duplicaat een
  // document dat over ander werk gaat — een verkeerd document bij een derde, zonder dat er iets
  // misgaat waar iemand op kan wijzen.
  //
  // Allebei de routes bouwen hun rij uit een EXPLICIETE kolommenlijst, dus vandaag klopt het
  // vanzelf. Deze poort maakt van dat toeval een afspraak: wie de kolom later toevoegt — een
  // volstrekt plausibele "verbetering" — krijgt hier rood in plaats van een verstuurde mail.
  for (const f of [
    "src/app/api/invoice/[id]/duplicate/route.ts",
    "src/app/api/cron/recurring/route.ts",
  ]) {
    assert.ok(
      !code(f).includes("attachment_document_id"),
      `${f} must not carry the attachment into a copy — an attachment is evidence about ONE job`,
    );
  }
  // En de reden staat op de plek waar iemand hem zoekt, niet alleen hier. readFileSync en niet
  // code(): de uitleg IS commentaar, en code() is precies de helper die commentaar weghaalt.
  assert.match(readFileSync("src/lib/invoice-attachment.ts", "utf8"), /EEN KOPIE KRIJGT DE BIJLAGE NIET MEE/,
    "the decision must be written where the feature is explained, or it reads as an omission");
});

// ─── [MIGRATIE-JOURNAAL] De inventarisvraag mag niet achterlopen op de map ────
//
// docs/WELKE_MIGRATIES_STAAN_ER.sql beantwoordt "wat staat er ÉCHT in de database?". De vorige
// versie stelde die vraag met een lijst die iemand met de hand bijhield, en schreef zelf op wat
// daar mis mee is:
//
//     "Het ANTWOORD komt uit de database, maar de VRAAG staat hier met de hand in. Een migratie
//      die er niet in staat, kan dit bestand ook niet 'OPEN' noemen."
//
// Dat ging twee keer mis. Eén keer dekte de lijst 17 van de 71 migraties en gaf een schoon "alles
// toegepast" terug — met de vier waar de hele betaalkant op leunt er niet in. Bij de laatste
// telling dekte hij er 28 van de 104.
//
// Het bestand wordt nu GEGENEREERD uit supabase/migrations/. Deze poort is wat die generatie waard
// maakt: hij faalt zodra de map en het bestand uit elkaar lopen. Een nieuwe migratie zonder
// regenereren is dan een rode poort in plaats van een lijst die stilletjes te weinig vraagt.

test("[MIGRATIE-JOURNAAL] the inventory query covers every migration on disk", () => {
  const sql = readFileSync("docs/WELKE_MIGRATIES_STAAN_ER.sql", "utf8");
  const opSchijf = readdirSync("supabase/migrations").filter((f) => f.endsWith(".sql")).sort();

  // Elke migratie komt óf als probe voor, óf staat expliciet bij "niet vast te stellen". Zwijgen
  // is de enige uitkomst die niet mag: dat is precies hoe de vorige versie te weinig vroeg.
  const ontbreekt = opSchijf.filter((f) => !sql.includes(f));
  assert.deepEqual(ontbreekt, [],
    "these migrations are on disk but absent from the inventory — regenerate with\n" +
    "  npx tsx scripts/migration-inventory.ts > docs/WELKE_MIGRATIES_STAAN_ER.sql\n  " +
    ontbreekt.join("\n  "));

  // …en andersom: een regel over een migratie die niet meer bestaat, vraagt naar niets.
  for (const m of sql.matchAll(/^ {2}\('([^']+\.sql)'/gm)) {
    assert.ok(opSchijf.includes(m[1]), `${m[1]} is probed but no longer exists in supabase/migrations/`);
  }

  // Met de hand bijwerken is de fout die dit alles veroorzaakte, dus dat moet er ook op staan.
  assert.match(sql, /automatisch gegenereerd, NIET met de hand bijwerken/);
  assert.match(sql, /scripts\/migration-inventory\.ts/, "the file must name the script that makes it");
});

test("[MIGRATIE-JOURNAAL] a migration that creates nothing is named, never guessed at", () => {
  // Een migratie die alleen intrekt (rpc_anon_revoke), alleen wijzigt (function_search_path) of
  // alleen data verplaatst (supplier_backfill) heeft geen object waarvan het BESTAAN iets bewijst.
  // Daar een vingerafdruk voor verzinnen zou een verkeerd antwoord geven in plaats van geen — en
  // een lijst die zwijgt over wat ze niet weet is de lijst waar dit bestand tegen is geschreven.
  const sql = readFileSync("docs/WELKE_MIGRATIES_STAAN_ER.sql", "utf8");
  const blok = sql.slice(sql.indexOf("NIET VAST TE STELLEN"));
  for (const f of ["rpc_anon_revoke.sql", "function_search_path.sql", "supplier_backfill.sql"]) {
    assert.ok(blok.includes(f), `${f} creates nothing and must be listed as undeterminable`);
    // …en dus NIET als probe, want dan zou hij voor eeuwig 'OPEN' heten.
    assert.ok(!sql.includes(`  ('${f}'`), `${f} must not be given an invented fingerprint`);
  }
});

test("[WAAROM-VASTGEHOUDEN] both branches of the auto-advance decision are written down", () => {
  // Gemeten op één echte administratie over een jaar: 350 van de 590 inkomende documenten hadden
  // een mensenhand nodig, en 296 daarvan droegen geen énkele vlag die verklaarde waarom.
  //
  // Niet omdat de app het niet wist. beslisAutoAdvance rekent voor elke weigering een precieze
  // reden uit — zeventien stuks — en het type noemt dat veld zelf "machine tag for
  // audit/telemetry". Hij werd alleen op de GESLAAGDE tak opgeschreven; bij een weigering
  // berekend en weggegooid, precies op het moment dat de app besluit de eigenaar een minuut te
  // kosten.
  //
  // Eén tak schrijven en de andere niet is hoe dit verdween, dus dat is wat hier vastligt: beide
  // paden, beide takken. Zonder deze meting is elke volgende versnelling een gok.
  for (const f of ["src/app/api/intake/route.ts", "src/lib/email-integration.ts"]) {
    const src = code(f);
    assert.match(src, /_auto_verified/, `${f}: the passing branch must stay written down`);
    assert.match(src, /_auto_hold/,
      `${f}: the REFUSING branch must be written down too. The reason is computed either way; ` +
      "discarding it on refusal makes the most expensive question in the product unanswerable");
    // …en met de reden erin, niet als kale vlag: "vastgehouden" zonder waarom is net zo blind.
    assert.match(src, /_auto_hold[\s\S]{0,160}?reason: autoAdv\.reason/,
      `${f}: the hold must carry the machine tag, or it says only that something happened`);
  }

  // De redenen zelf moeten blijven bestaan waar ze worden gemaakt — een lege string terugbrengen
  // zou de poort hierboven groen laten en de meting alsnog waardeloos maken.
  const beslis = code("src/lib/auto-advance.ts");
  const redenen = [...beslis.matchAll(/advance: false, reason: ["`']([a-z_]+)/g)].map((m) => m[1]);
  assert.ok(redenen.length >= 10,
    `only ${redenen.length} refusal reasons found; the decision was flattened and the measurement ` +
    "loses exactly the detail it exists for");
  assert.ok(new Set(redenen).size === redenen.length,
    "two refusals share one tag, so they cannot be told apart in the measurement");
});

test("[WAAROM-VASTGEHOUDEN] every refusal tag has a sentence an operator can act on", () => {
  // De werklijst op het beheerscherm rangschikt machinecodes. `no_reliable_total` is voor de code
  // precies genoeg en voor de mens die moet besluiten wat hij als volgende bouwt, niets.
  //
  // Dit is een SCAN, geen tweede lijst. Twee met de hand bijgehouden lijsten kloppen eeuwig met
  // elkaar en nooit met de werkelijkheid — dat is vandaag twee keer misgegaan. Deze poort leest de
  // bestanden die de codes MAKEN, en een nieuwe weigering zonder zin laat hem vallen.
  const bronnen = [
    "src/lib/auto-advance.ts",
    "src/app/api/intake/route.ts",
    "src/lib/email-integration.ts",
  ];
  const gevonden = new Set<string>();
  for (const f of bronnen) {
    const src = code(f);
    for (const m of src.matchAll(/advance: false[^}]*\}/g)) {
      const staart = m[0].slice(m[0].indexOf("reason:"));
      for (const tag of staart.matchAll(/["'`]([a-z][a-z0-9_]*)["'`]/g)) gevonden.add(tag[1]);
    }
  }
  assert.ok(gevonden.size >= 15,
    `only ${gevonden.size} refusal tags found across ${bronnen.length} files; the scan stopped ` +
    "matching what it is supposed to watch, which leaves the check green and blind");
  for (const tag of gevonden) {
    assert.ok(HOLD_LABELS[tag],
      `refusal tag "${tag}" has no sentence in HOLD_LABELS. It would still be counted and shown — ` +
      "as the raw tag — but the operator ranking exists to say which fix buys back the most time, " +
      "and a machine word answers a different question than the one being asked");
  }
});

test("[WAAROM-WACHT] every refusal the owner can meet has a sentence, and none of them is a code", () => {
  // Dezelfde scan als de poort hierboven, maar voor de andere lezer. Het beheerpaneel mag een
  // onbekende code tonen als zichzelf — daar is het informatie. Op de kaart van de eigenaar is
  // `no_reliable_total` geen uitleg maar ruis, dus toont why-waiting.ts daar niets. En "niets"
  // is precies de stand die stil kan verbergen dat een veelvoorkomend geval nooit is uitgelegd —
  // vandaar deze poort.
  const bronnen = [
    "src/lib/auto-advance.ts",
    "src/app/api/intake/route.ts",
    "src/lib/email-integration.ts",
  ];
  const gevonden = new Set<string>();
  for (const f of bronnen) {
    for (const m of code(f).matchAll(/advance: false[^}]*\}/g)) {
      const staart = m[0].slice(m[0].indexOf("reason:"));
      for (const tag of staart.matchAll(/["'`]([a-z][a-z0-9_]*)["'`]/g)) gevonden.add(tag[1]);
    }
  }
  assert.ok(gevonden.size >= 15, `only ${gevonden.size} refusal tags found; the scan went blind`);

  const uitlegbaar = new Set(explainableReasons());
  for (const tag of gevonden) {
    assert.ok(uitlegbaar.has(tag),
      `refusal tag "${tag}" reaches the owner's queue with no sentence, so that card explains ` +
      "nothing at all — the owner re-reads a document that was read correctly and learns nothing");
  }

  // …en geen enkele zin die eruit komt mag alsnog een machinewoord zijn.
  for (const tag of uitlegbaar) {
    const zin = explainWaiting(tag, {}, "nl");
    assert.ok(zin && !/[a-z]{3,}_[a-z_]{3,}/.test(zin.text),
      `the sentence for "${tag}" reads like a machine tag, which is the thing it replaces`);
  }

  // ── En hetzelfde één scherm verder ────────────────────────────────────────────────────────
  //
  // /bank kent zijn eigen redenen (bank-waiting-reason.ts) en ze horen in DEZELFDE woordenlijst.
  // Een aparte lijst per scherm is precies hoe de ene helft vertaald raakt en de andere niet.
  const bankBron = code("src/lib/bank-waiting-reason.ts");
  const unie = bankBron.slice(bankBron.indexOf("export type BankWaitReason ="));
  const bankTags = [...unie.slice(0, unie.indexOf(";")).matchAll(/"([a-z_]+)"/g)].map((m) => m[1]);
  assert.ok(bankTags.length >= 4,
    `only ${bankTags.length} bank reasons found; the scan stopped matching the union it watches`);
  for (const tag of bankTags) {
    assert.ok(uitlegbaar.has(tag),
      `bank reason "${tag}" has no sentence, so that line falls back to the one paragraph the ` +
      "whole tab shares — true of every line in it and useful about none of them");
  }

  // En de weg ernaartoe: de route moet het oordeel ook echt meesturen. Een uitleg die nergens
  // wordt berekend is onzichtbaar op precies dezelfde manier als een uitleg die niet bestaat.
  const bankRoute = code("src/app/api/bank/match/route.ts");
  assert.match(bankRoute, /judgeBankWait\(/,
    "the match route must compute the reason, or the card has nothing to render");
  assert.match(bankRoute, /waitReason:/,
    "…and put it on the DTO the screen reads");

  // ── En het categorisatiescherm ────────────────────────────────────────────────────────────
  const catBron = code("src/lib/category-wait.ts");
  const catUnie = catBron.slice(catBron.indexOf("export type CategoryWaitReason ="));
  const catTags = [...catUnie.slice(0, catUnie.indexOf(";")).matchAll(/"([a-z_]+)"/g)].map((m) => m[1]);
  assert.ok(catTags.length >= 3,
    `only ${catTags.length} category reasons found; the scan stopped matching its own union`);
  for (const tag of catTags) {
    assert.ok(uitlegbaar.has(tag), `category reason "${tag}" reaches the screen with no sentence`);
  }
  const catRoute = code("src/app/api/bank/categorize/route.ts");
  assert.match(catRoute, /judgeCategoryWait\(/, "the categorize route must compute the reason");
  assert.match(catRoute, /wait_reason:/, "…and put it on the DTO the screen reads");

  // En het label dat loog. Een geheugen dat de ANDERE kant op wijst mag nooit hetzelfde woord
  // krijgen als een geheugen waar de app zeker van is — dat was de hele bevinding.
  assert.notEqual(
    categoryHint({ source: "memory", waitReason: "memory_contradicts_direction", confident: false }).key,
    categoryHint({ source: "memory", waitReason: null, confident: true }).key,
    "a contradicted memory and a trusted one must not share a label: the suggestion the app " +
    "distrusts would look exactly like the one it trusts most, on a screen about money direction",
  );
  assert.doesNotMatch(
    code("src/app/dashboard/bank/categoriseren/CategoriseClient.tsx"),
    /t\('cat\.onthouden'\)/,
    "the screen must choose its label through categoryHint, where the distinction is tested",
  );
});

test("[KAS-ACHTER-BANK] what the pass deliberately did not book reaches the owner, not only a log", () => {
  // De regel onderaan runBankAutoConfirm stond er al: "refusals this run", naar console.info. De
  // eigenaar zat naar precies die regels te kijken en kreeg geen woord. Deze poort houdt de weg
  // van de beslissing naar het scherm open — hij loopt over drie bestanden en elk ervan kan hem
  // in z'n eentje afknippen zonder dat er iets rood wordt.
  const pas = code("src/lib/bank-auto-confirm.ts");
  assert.match(pas, /refusalsOut/,
    "the pass must be able to hand its refusals back; eleven callers depend on the array it " +
    "returns, so this travels as an out-parameter rather than a wider return type");
  assert.match(pas, /Object\.assign\(args\.refusalsOut, kasRefusals\)/,
    "…and must actually fill it, with the same tally the log line prints");

  const route = code("src/app/api/bank/auto-confirm/route.ts");
  assert.match(route, /refusalsOut:/, "the route must ask for the tally");
  assert.match(route, /kasRefusals\s*[,}]/, "…and put it in the response");

  const scherm = code("src/app/dashboard/bank/BankClient.tsx");
  assert.match(scherm, /json\.kasRefusals/, "the screen must read it");
  // De twee standen zijn niet inwisselbaar: 'filed_quarter' is de app die het goed doet,
  // 'unknown_filing' is de app die het niet WEET. Zou het scherm er één zin van maken, dan leest
  // een stilgevallen controle als een weloverwogen beslissing.
  assert.match(scherm, /bank\.kas\.aangegeven/);
  assert.match(scherm, /bank\.kas\.onbekend/);
  assert.notEqual(MESSAGES["bank.kas.aangegeven"].nl, MESSAGES["bank.kas.onbekend"].nl,
    "a deliberate refusal and a check that could not run must never say the same thing");
  for (const k of ["bank.kas.aangegeven", "bank.kas.onbekend"] as const) {
    assert.match(MESSAGES[k].nl, /\{count\}/, `${k} must name how many, or it is a mood, not a fact`);
  }
});

test("[GEGROND-STAAT-IN] the witness reaches BOTH doors, and stays the narrow one", () => {
  // Dit is een GELDPOORT die wijder is gezet. De reden dat dat verantwoord is, staat of valt met
  // drie dingen, en alle drie kunnen stilletjes verdwijnen bij een latere opruiming.
  //
  // 1. Beide schrijvers moeten het signaal doorgeven. Doet er één het niet, dan boekt dezelfde
  //    factuur wél vanzelf via de upload en niet via de mail — en dat verschil is onzichtbaar.
  for (const f of ["src/app/api/intake/route.ts", "src/lib/email-integration.ts"]) {
    assert.match(code(f), /moneyGroundedInText: moneyGroundedInText\(/,
      `${f}: passes no document evidence, so this door is dead on that path while it is open on ` +
      "the other — the same invoice would then book itself through one entrance and not the other");
  }

  // 2. OCR mag nooit invallen voor de zelfscore van het model. amount-grounding.ts zegt het zelf:
  //    die getuige is "a model, from the same family as the extractor… Corroboration, not proof".
  //    Laat je hem toe, dan beoordeelt het model zijn eigen lezing — precies de cirkel die dat
  //    bestand bestaat om te doorbreken.
  assert.equal(moneyGroundedInText({ _grounding: { totalIncBtw: "found", totalExBtw: "found", btwAmount: "found", source: "ocr" } }), false,
    "the OCR witness may corroborate, never stand in for the model's own confidence");
  assert.equal(moneyGroundedInText({ _grounding: { totalIncBtw: "found", totalExBtw: "found", btwAmount: "found" } }), true);
  // …en het blijft ALLE DRIE. Eén ontbrekend bedrag is niet de getuige waar deze deur om vraagt.
  assert.equal(moneyGroundedInText({ _grounding: { totalIncBtw: "found", totalExBtw: "found", btwAmount: "absent" } }), false);

  // 3. De boeking moet zeggen door WELKE deur ze kwam, anders is "hoe vaak vuurde de nieuwe deur,
  //    en kwam er iets van terug als correctie" geen vraag maar een gok.
  const beslis = code("src/lib/auto-advance.ts");
  assert.match(beslis, /clean_grounded_in_document/,
    "a booking that leaned on the document instead of a score must carry its own name");
  assert.ok(/grondedInPlaatsVanScore \? "clean_grounded_in_document" : "clean_high_confidence"/.test(beslis),
    "the two doors may not collapse back into one reason — the ternary that tells them apart is gone");
});

test("[SEGMENT-VOORDEUR] every promise on a segment page names a screen that exists", () => {
  // Een landingspagina is de enige plek in dit product waar een belofte kan blijven staan nadat
  // het scherm eronder is verdwenen — niemand die aan /dashboard/uren werkt komt langs een
  // marketingtekst. /voor-boekhouders stelt de regel al ("ONLY WHAT EXISTS. No binnenkort"); dit
  // is die regel als test in plaats van als voornemen.
  for (const route of claimedRoutes()) {
    assert.ok(existsSync(`src/app/dashboard/${route}/page.tsx`),
      `een segmentpagina belooft /dashboard/${route}, en dat scherm bestaat niet. Haal de belofte ` +
      "weg of bouw het scherm — een pagina die iets belooft dat er niet is, kost het hele kanaal");
  }

  for (const p of SEGMENT_PAGES) {
    // De deur zelf.
    assert.ok(existsSync(`src/app/voor-${p.slug}/page.tsx`), `route /voor-${p.slug} ontbreekt`);
    // …en in de sitemap, want anders bestaat hij voor niemand. De publieke rooktest loopt élke
    // URL uit sitemap.xml af, dus deze regel levert meteen een echte laadcontrole op.
    assert.match(code("src/app/sitemap.ts"), new RegExp(`/voor-${p.slug}\``),
      `/voor-${p.slug} staat niet in de sitemap`);
    // …en de middleware moet hem doorlaten. Dit is de derde bron uit public-surface.spec.ts, maar
    // dan in een unit-test: de rooktest ving deze fout pas als láátste stap van `npm run gates`,
    // na een volledige build. Alle drie de deuren stonden in de sitemap en gaven een 307 naar
    // /login — onzichtbaar voor iedere bezoeker en iedere crawler, en het scherm zelf mankeerde
    // niets. Een lijst die met de hand wordt bijgehouden naast een automatische regel faalt altijd
    // zo; deze regel leidt de eis af uit SEGMENT_PAGES in plaats van hem te herhalen.
    // isPublic() en niet de lijst zelf: dit is de beslissing die de middleware werkelijk neemt,
    // prefixregel en al, in plaats van een kopie van de gegevens waarop hij stoelt.
    assert.ok(isPublic(`/voor-${p.slug}`),
      `/voor-${p.slug} komt niet door de middleware — elke uitgelogde bezoeker krijgt /login, en ` +
      "dat is precies de lezer voor wie deze pagina geschreven is");

    // [NO-SILENT-EMPTY], toegepast op marketing: de eerlijke sectie mag nooit leeg zijn. Een
    // pagina die alleen kan opsommen wat wél kan, is een pagina waar de lezer bij het eerste
    // gemis achter komt in plaats van vooraf.
    assert.ok(p.nietDit.length > 0,
      `${p.slug}: geen enkele "wat dit niet doet" — dat is geen product zonder grenzen, dat is een ` +
      "pagina die ze verzwijgt");
    assert.ok(p.stappen.length >= 3, `${p.slug}: te weinig stappen om iets uit te leggen`);
    // De belofte is de H1. Hij mag niet over boekhouden gaan maar over wat de lezer terugkrijgt.
    assert.doesNotMatch(p.belofte.toLowerCase(), /boekhoud/,
      `${p.slug}: de kop verkoopt "boekhouding". Niemand wordt wakker met die wens — verkoop de ` +
      "stapel die weggaat");
  }

  // Drie deuren, drie slugs, geen dubbele.
  const slugs = SEGMENT_PAGES.map((p) => p.slug);
  assert.equal(new Set(slugs).size, slugs.length, "twee segmenten delen een slug");

  // De route moet zijn EIGEN pagina ophalen. segmentBySlug() geeft undefined terug bij een
  // hernoemde slug, en de routes gebruiken `!` — dus een hernoeming zonder deze regel levert geen
  // typefout op maar een lege pagina in productie.
  for (const p of SEGMENT_PAGES) {
    assert.match(code(`src/app/voor-${p.slug}/page.tsx`), new RegExp(`segmentBySlug\\('${p.slug}'\\)`),
      `src/app/voor-${p.slug}/page.tsx haalt niet zijn eigen segment op — na een hernoeming van de ` +
      "slug rendert deze route niets, en geen enkele typecontrole ziet dat");
  }

  // Elke link op de deur wijst naar een pagina die bestaat. Dezelfde regel als hierboven, maar dan
  // voor de uitweg: een landingspagina met een dode "Gratis beginnen" is erger dan geen pagina.
  //
  // Leest twee vormen, en dat is geleerd in plaats van bedacht: toen de aanmeldknop van een vaste
  // href een berekende werd (`href={aanmeldHref}`, om het vak mee te dragen), zag de eerste versie
  // van deze scan alleen /prijzen nog en viel om op zijn eigen ondergrens. Dat was terecht — hij
  // was half blind geworden — maar het laat zien hoe stil een linkcontrole kapot gaat: hij blijft
  // groen zolang er tóevallig genoeg letterlijke links overblijven.
  const bron = code("src/components/SegmentVoordeur.tsx");
  const hrefs = [
    ...[...bron.matchAll(/href="(\/[^"#?]*)/g)].map((m) => m[1]),
    // De berekende variant: `/register?...` of `/register`, opgebouwd uit één basispad.
    ...[...bron.matchAll(/`(\/[a-z-]+)(?:\?|`)/g)].map((m) => m[1]),
    ...[...bron.matchAll(/: '(\/[a-z-]+)'/g)].map((m) => m[1]),
  ].filter((h) => h !== "/");
  assert.ok(hrefs.includes("/register"),
    "de aanmeldknop wijst niet meer naar /register — of de scan leest de berekende vorm niet meer");
  assert.ok(hrefs.length >= 2, "de deur heeft geen knoppen meer — of de scan leest ze niet");
  for (const h of new Set(hrefs)) {
    assert.ok(existsSync(`src/app${h}/page.tsx`), `SegmentVoordeur linkt naar ${h}, en dat bestaat niet`);
  }
});

test("[WAAROM-DEZE] elk matchsignaal kan op het bankscherm worden uitgelegd", () => {
  // Gemeld met een schermafbeelding: kandidaten die "maar wat" leken. Eén oorzaak daarvan was dat
  // WHY_KEY vier van de tien signalen kende. Een kandidaat die op het rekeningnummer van de
  // leverancier was gevonden — sterker bewijs bestaat er niet, op een factuurnummer na — toonde
  // alleen "datum dichtbij". De uitleg bestond, werd berekend, en kwam er als de zwakste
  // beschikbare uit; dat is [NO-SILENT-EMPTY] op een uitleg in plaats van op een fout.
  //
  // Afgeleid uit het type, niet uit een lijst ernaast: dat is de derde keer vandaag dat een
  // handmatig bijgehouden lijst naast een automatische regel verlopen bleek.
  const bron = code("src/lib/bank-matching.ts");
  const blok = bron.slice(bron.indexOf("export type MatchSignal ="));
  const signalen = [...blok.slice(0, blok.indexOf(";")).matchAll(/"([a-z_]+)"/g)].map((m) => m[1]);
  assert.ok(signalen.length >= 10, `de scan vond maar ${signalen.length} signalen — leest hij het type nog?`);

  const scherm = code("src/app/dashboard/bank/BankClient.tsx");
  const tabel = scherm.slice(scherm.indexOf("const WHY_KEY = {"));
  const gedekt = new Set([...tabel.slice(0, tabel.indexOf("} as const")).matchAll(/^\s*([a-z_]+):/gm)].map((m) => m[1]));

  const ongedekt = signalen.filter((sig) => !gedekt.has(sig));
  assert.deepEqual(ongedekt, [],
    `deze matchsignalen kan het bankscherm niet uitleggen: ${ongedekt.join(", ")}. Een kandidaat die ` +
    "op zo'n reden is gevonden toont dan de zwakste reden die hij toevallig óók heeft, en leest als " +
    "een gok. Zet ze in WHY_KEY met een zin in messages.ts");

  // …en elke sleutel die WHY_KEY noemt moet bestaan, anders staat er straks een sleutel op het scherm.
  for (const sleutel of [...tabel.slice(0, tabel.indexOf("} as const")).matchAll(/'(bank\.why\.[A-Za-z]+)'/g)].map((m) => m[1])) {
    assert.match(code("src/lib/i18n/messages.ts"), new RegExp(`'${sleutel.replace(/\./g, "\\.")}'`),
      `${sleutel} staat in WHY_KEY maar niet in messages.ts`);
  }
});

test("[AL-GEBOEKT] de kiezer staat uit zodra de betaling een afgeboekte factuur noemt", () => {
  // De gevaarlijke helft van de melding: onder de kop stonden facturen van dezelfde leverancier die
  // NIET bij deze betaling hoorden. Eén tik boekt dan een openstaande rekening af met geld dat er
  // niet voor was. De render-test tests/render/bank-al-geboekt.test.tsx bewijst het gedrag; deze
  // poort houdt de bedrading vast, want die is met één weggehaalde `!` weer stuk.
  // Per REGEL, en niet met indexOf over het hele bestand: de eerste versie hiervan vond
  // `s.outcome === 'choice'` in een filter zeshonderd regels hoger en keek dáár terug. Hij faalde
  // dus op correcte code — precies de poort die wordt weggeklikt en daarna niets meer bewaakt.
  const regels = code("src/app/dashboard/bank/BankClient.tsx").split("\n");
  const takken = regels.filter((r) => /s\.outcome === '(choice|auto)'/.test(r) && r.includes("&& ("));
  assert.ok(takken.length >= 2, `maar ${takken.length} rendertakken gevonden — is de kaart herschreven?`);
  for (const tak of takken) {
    assert.match(tak, /!s\.quotedSettled/,
      `deze rendertak kijkt niet of de betaling een al afgeboekte factuur noemt, dus de kiezer komt ` +
      `terug: ${tak.trim().slice(0, 80)}`);
  }
  // En de server moet het veld überhaupt sturen.
  assert.match(code("src/app/api/bank/match/route.ts"), /quotedSettled:/,
    "de matchroute stuurt quotedSettled niet meer mee — dan staat de kiezer er in productie weer");
});

test("[DEMO-DICHT] een cron die namens een eigenaar mailt, slaat het demoaccount over", () => {
  // Het gat dat gisteren openbleef. De fence in de middleware kijkt naar de SESSIEGEBRUIKER, en
  // een cron heeft er geen — die routes zijn dus nooit langs die fence gekomen. Gemeten op
  // 3 september: het demoaccount, met een openbaar wachtwoord, was het ENIGE profiel met
  // herinneringen aan, met een openstaande factuur aan een verzonnen fysiopraktijk. Nu
  // herinneringen standaard aanstaan is dat geen theorie meer.
  //
  // De grens per cron: mailt hij een DERDE (de klant van de eigenaar), dan is het een brief die
  // niet terug kan. Mailt hij de eigenaar zelf, dan is het een bounce naar een verzonnen adres —
  // minder erg, maar bounces zijn precies wat [BEZORGING] heeft opgeruimd. Allebei overslaan dus,
  // en welke cron dat moet doen wordt AFGELEID uit wie er mailt én over eigenaren loopt.
  const crons = execSync(
    "grep -rl '@/lib/email' src/app/api/cron --include=route.ts || true",
    { encoding: "utf8" },
  ).split("\n").filter(Boolean);
  assert.ok(crons.length >= 4, `maar ${crons.length} mailende crons gevonden — leest de scan nog mee?`);

  const ongedekt: string[] = [];
  for (const f of crons) {
    const src = code(f);
    // Alleen crons die zélf over profielen lopen kunnen een eigenaar overslaan. Een cron die op
    // een rij begint die de demo nooit heeft (een mailbox, een betaalverzoek) heeft niets te doen.
    if (!/from\("profiles"\)/.test(src)) continue;
    // GEBRUIKT, niet alleen geïmporteerd. De eerste versie vroeg `src.includes("DEMO_TENANT_ID")`,
    // en die was al waar door de import-regel alleen: de negatieve controle haalde de filterregel
    // weg en de poort bleef groen. Een bewering die niet kan falen bewaakt niets — dezelfde les
    // als de kandidaat die "datum dichtbij" toonde en de dimensie die undefined met undefined
    // vergeleek. Dus: de identifier moet buiten de imports voorkomen, in een echte filterregel.
    const zonderImports = src.split("\n").filter((r) => !/^\s*import\s/.test(r)).join("\n");
    if (!/\.neq\(\s*"id"\s*,\s*DEMO_TENANT_ID\s*\)/.test(zonderImports)) ongedekt.push(f);
  }
  assert.deepEqual(ongedekt, [],
    "deze crons lopen over eigenaren en versturen mail, maar slaan het demoaccount niet over — " +
    `het wachtwoord daarvan is openbaar: ${ongedekt.join(", ")}`);
});

test("[HERINNER-AAN] de rem op de oude stapel zit in de cron, niet alleen in de functie", () => {
  // Herinneringen staan sinds 3 september standaard AAN. De veiligheid daarvan hangt aan één
  // argument dat de cron moet meegeven: reminderTierDue() geeft de HOOGST bereikte trap terug, dus
  // zonder dat argument stuurt de eerste ronde van een net geregistreerd account de
  // ingebrekestelling — mét incassokosten — naar iedereen in een geïmporteerde administratie.
  //
  // De unittests dekken de functie; ze kunnen niet zien of de aanroeper het argument nog meegeeft.
  // Precies dat gat viel in de negatieve controle: het argument weghalen liet elke test groen.
  const cron = code("src/app/api/cron/reminders/route.ts");
  assert.match(cron, /remindersActiveSinceDay:/,
    "de herinneringscron geeft het aanzetmoment niet meer mee — dan jaagt een nieuw account op " +
    "zijn hele geïmporteerde stapel, met de zwaarste trap, in één ronde");
  assert.match(cron, /reminders_enabled_at/,
    "de cron leest reminders_enabled_at niet meer op, dus het moment kan nergens vandaan komen");

  // En de schakelaar moet stempelen bij het AANZETTEN, anders is het moment altijd leeg en valt de
  // rem terug op "geen rem".
  assert.match(code("src/app/dashboard/settings/page.tsx"), /reminders_enabled_at: new Date\(\)\.toISOString\(\)/,
    "het instellingenscherm zet reminders_enabled_at niet meer bij het aanzetten");
});

test("[HERINNER-AAN] de migratie zet de standaard om én vult het moment voor bestaande rijen", () => {
  // Twee helften, en de tweede is de belangrijkste: zonder de backfill zou elke bestaande eigenaar
  // een leeg moment krijgen. Dat is "geen rem", en dat is hier het VEILIGE antwoord (hun gedrag
  // verandert niet) — maar de migratie hoort het expliciet te doen in plaats van erop te gokken.
  // Géén STAND_CONTROLE-regel: deze migratie voegt een KOLOM toe en heeft daarmee een gewone
  // vingerafdruk. scripts/migration-inventory.ts weigert allebei tegelijk, met de reden erbij —
  // "twee metingen op hetzelfde gaan uit elkaar lopen". De eerste versie van deze poort zette hem
  // er toch in en brak de generator.
  const mig = code("supabase/migrations/reminders_on_by_default.sql");
  assert.match(mig, /ALTER COLUMN reminders_enabled SET DEFAULT true/,
    "de standaard gaat niet aan");
  assert.match(mig, /UPDATE public\.profiles[\s\S]*reminders_enabled_at = COALESCE\(created_at/,
    "bestaande rijen krijgen geen aanzetmoment, dus hun gedrag verandert stilzwijgend mee");
});

// ── [AL-GEBOEKT-KLEMT] ────────────────────────────────────────────────────────────────────────
//
// [AL-GEBOEKT] removes the CHOOSER when the payment names an invoice that is already booked. It
// does not, by itself, remove the three ways that payment still gets booked without a choice:
//
//   1. the winner is PRE-SELECTED on load, which is what makes "Bevestig betaling" one tap;
//   2. selectedCand falls back to `s.best` when nothing was selected, so the confirm has a target
//      even though the owner never picked one;
//   3. isServerAutoBookable still counts the row, so the bulk "N zekere betalingen" books it
//      without the card ever being opened.
//
// Any one of them books an open invoice with money that belonged to a bill already settled — which
// is the whole harm the card exists to prevent. Two sessions arrived at the same verdict from
// different directions and the guards were merged onto the surviving one; this gate holds them
// there, because each is one deleted `!` away from being gone with nothing else complaining.
test("[AL-GEBOEKT-KLEMT] an already-booked payment is not pre-selected, not confirmed and not bulk-booked", () => {
  const scherm = code("src/app/dashboard/bank/BankClient.tsx");

  // 1. Nothing is pre-selected while the payment names a settled invoice.
  assert.match(scherm, /if \(s\.outcome === 'auto' && s\.best && !s\.quotedSettled\) pre\[s\.transactionId\] = s\.best\.invoiceId/,
    "the pre-selection runs again on a payment that names an already-booked invoice — that is the " +
    "green check over a bill the statement never named, with a live confirm under it");

  // 2. No silent fallback to the winner. An explicit tap still selects a candidate; that path is
  //    deliberately untouched, so the owner keeps every deliberate action.
  assert.match(scherm, /\(s\.outcome === 'auto' && !s\.quotedSettled \? s\.best : null\)/,
    "selectedCand falls back to the winner again, so the confirm has a target nobody chose");

  // 3. The bulk action skips the row. Read from the predicate itself, not from the file, so a guard
  //    that moved somewhere else cannot pass this by accident.
  const blok = scherm.slice(scherm.indexOf("function isServerAutoBookable"));
  const lijf = blok.slice(0, blok.indexOf("\n}"));
  assert.match(lijf, /if \(s\.quotedSettled\) return false/,
    "isServerAutoBookable counts an already-booked payment again — the bulk books it without the " +
    "card ever being opened");
  assert.ok(lijf.length < 2000, `the predicate scan ran past its function (${lijf.length} chars)`);
});

test("[RLS-AAN] een migratie die een tabel maakt, zet er row level security op", () => {
  // Gemeten op productie op 2 september, als het demoaccount met een openbaar wachtwoord:
  //   · 612 facturen in de database, 17 zichtbaar, 0 van iemand anders;
  //   · 1551 banktransacties, 15 zichtbaar, 0 van iemand anders;
  //   · een UPDATE op de 555 rijen van de echte eigenaar raakte er 0;
  //   · een INSERT met andermans receiver_id werd geweigerd — 42501, new row violates row-level
  //     security policy.
  // En de tegenproef: als de echte eigenaar zijn 555 facturen zichtbaar, waarvan 0 van de demo. De
  // scheiding is dus identiteitsafhankelijk en geldt beide kanten op. Alle 35 tabellen in `public`
  // hebben RLS aan staan.
  //
  // Dat is de stand van vandaag, en die stand is precies wat een test hoort vast te houden. Het
  // risico is niet dat de policies van nu fout zijn — dat is gemeten — maar dat de tabel van
  // volgende maand zonder RLS naar productie gaat. Dan is er geen foutmelding en geen leeg scherm:
  // alles werkt, en iedereen ziet alles. seed-demo-account.sql leunt er in zoveel woorden op
  // ("RLS already isolates it, so the screenshots are clean by construction") en sinds het
  // wachtwoord van dat account openbaar is, is die aanname het enige wat tussen een vreemde en
  // 612 facturen van een echt bedrijf staat.
  //
  // Deze poort kan geen database bevragen (de build draait zonder secrets, LIVE_GAAN.md §0), dus
  // hij leest de migraties. scripts/verify-tenant-isolation.mts doet de echte proef tegen een
  // levende database, en de meting hierboven komt daarvandaan.
  const zonderRls: string[] = [];
  for (const file of readdirSync("supabase/migrations").filter((f) => f.endsWith(".sql"))) {
    // Commentaar eerst weg. De eerste versie van deze scan las de ZIN "Idempotent: CREATE TABLE IF
    // NOT EXISTS + guarded policies" in accountant_subject_status.sql als een tabel met de naam
    // "if" — een poort die een toelichting aanziet voor code beschuldigt uiteindelijk iets dat
    // klopt, en dat is de soort poort die wordt weggeklikt.
    const sql = code(`supabase/migrations/${file}`)
      .replace(/\/\*[\s\S]*?\*\//g, " ")
      .split("\n").map((r) => r.replace(/--.*$/, "")).join("\n");

    const gemaakt = [...sql.matchAll(/CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:public\.)?([A-Za-z0-9_]+)/gi)]
      .map((m) => m[1].toLowerCase());
    if (gemaakt.length === 0) continue;

    const aan = new Set(
      [...sql.matchAll(/ALTER\s+TABLE\s+(?:public\.)?([A-Za-z0-9_]+)\s+ENABLE\s+ROW\s+LEVEL\s+SECURITY/gi)]
        .map((m) => m[1].toLowerCase()),
    );
    for (const t of gemaakt) if (!aan.has(t)) zonderRls.push(`${file}: ${t}`);
  }

  assert.deepEqual(zonderRls, [],
    "deze migraties maken een tabel en zetten er geen row level security op. Zonder RLS is de " +
    "tabel voor iedere ingelogde gebruiker leesbaar, en dat valt nergens op — er breekt niets, er " +
    `is geen foutmelding, iedereen ziet gewoon alles: ${zonderRls.join(", ")}`);
});

test("[DEMO-DICHT] elke route die mail verstuurt of geld kost, is dicht voor het demoaccount", () => {
  // Het wachtwoord van demo@boekbrug.nl staat in een PUBLIEKE repository en staat daar voorgoed —
  // roteren helpt tegen het vorige wachtwoord, niet tegen `git log -p`. De bescherming is dus geen
  // geheim maar een grens, en een grens die met de hand wordt bijgehouden verloopt. Vandaag ging
  // dat twee keer mis (de icoonsubset, en PUBLIC_PATHS tegenover drie landingspagina's die naar
  // /login stuurden), dus deze poort LEIDT de verzameling af uit de broncode.
  //
  // De regel: importeert een API-route @/lib/email of @/lib/ai, dan gaat er post naar buiten of
  // geld naar het model, en dan hoort hij achter demoRefusalFor().
  const routes = execSync(
    "grep -rl -e \"@/lib/email\" -e \"@/lib/ai\" src/app/api --include=route.ts || true",
    { encoding: "utf8" },
  ).split("\n").filter(Boolean);
  assert.ok(routes.length >= 15, `de scan vond maar ${routes.length} routes — leest hij nog wel mee?`);

  const ongedekt: string[] = [];
  for (const file of routes) {
    const pathname = "/" + file.replace(/^src\/app\//, "").replace(/\/route\.ts$/, "")
      .replace(/\[([^\]]+)\]/g, "id");

    // Cronroutes draaien op een bearer token (CRON_SECRET), niet op een sessie: het demoaccount
    // heeft dat token niet en de middleware kijkt naar de sessiegebruiker. Die uitzondering wordt
    // hier BEWEZEN in plaats van aangenomen — een cronroute zonder tokencontrole is geen
    // uitzondering maar een gat.
    if (file.includes("/api/cron/")) {
      assert.match(code(file), /CRON_SECRET/,
        `${file} staat onder /api/cron maar controleert geen CRON_SECRET — dan is "cron" geen ` +
        "reden om hem buiten de demogrens te laten");
      continue;
    }
    // Een webhook wordt door de leverancier aangeroepen en draagt geen sessie, dus hij is nooit
    // "het demoaccount dat iets doet". Ook die uitzondering wordt bewezen: zonder handtekening
    // over de body is het geen webhook maar een open deur, en dan telt het argument niet.
    if (/\/api\/[^/]+\/webhook\//.test(file)) {
      assert.match(code(file), /signature|svix|WEBHOOK_SECRET/i,
        `${file} heet een webhook maar controleert geen handtekening — dan is "de leverancier belt ` +
        'aan" geen reden om hem buiten de demogrens te laten');
      continue;
    }

    if (demoRefusalFor(pathname, "POST") === null) ongedekt.push(pathname);
  }

  assert.deepEqual(ongedekt, [],
    "deze routes versturen mail of kosten geld en staan open voor een account waarvan het " +
    `wachtwoord openbaar is: ${ongedekt.join(", ")}. Zet ze in demo-tenant.ts`);
});

